import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    while True:
        position = stream.tell()
        line = stream.readline()
        if not line:
            return {"columns": [], "rows": []}
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        stream.seek(position)
        break

    previous_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > previous_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(stream, delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    existing = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "column_{}".format(number)
        while name in existing:
            number += 1
            name = "column_{}".format(number)
        columns.append(name)
        existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
